-- ----------------------------
-- Table structure for base_sys_param
-- ----------------------------
DROP TABLE IF EXISTS `base_sys_param`;
CREATE TABLE `base_sys_param`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `createTime` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '建立時間',
  `updateTime` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '更新時間',
  `tenantId` int NULL DEFAULT NULL COMMENT '租戶ID',
  `keyName` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '鍵',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '名稱',
  `data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '資料',
  `dataType` int NOT NULL DEFAULT 0 COMMENT '資料型別 0-字串 1-富文本 2-檔案 ',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '備註',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `IDX_cf19b5e52d8c71caa9c4534454`(`keyName` ASC) USING BTREE,
  INDEX `IDX_7bcb57371b481d8e2d66ddeaea`(`createTime` ASC) USING BTREE,
  INDEX `IDX_479122e3bf464112f7a7253dac`(`updateTime` ASC) USING BTREE,
  INDEX `IDX_8a0ab598ca7d63475356ca1157`(`tenantId` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 23 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of base_sys_param
-- ----------------------------
INSERT INTO `base_sys_param` VALUES (5, '2026-05-07 17:23:46', '2026-05-07 17:23:46', NULL, 'duty', '稅', '5%', 0, NULL);
INSERT INTO `base_sys_param` VALUES (6, '2026-05-14 12:08:48', '2026-05-16 11:12:42', NULL, 'quote_terms', '報價單預設條款', '[\n  {\n    \"title\": \"工作內容\",\n    \"items\": [\n      {\n        \"no\": 1,\n        \"text\": \"本報價單雙方簽署後視同正式合約。各項服務內容詳閱本報價單及其附件。甲方委託乙方執行委刊單所載產品內容、規格、數量等專案專案之工作，及其工作執行之目的、需求、方式等要求。\"\n      },\n      {\n        \"no\": 2,\n        \"text\": \"本合約所稱專案總價，指乙方執行專案所需費用，不包括產品購買、通訊、運費、舉辦抽獎活動、場景租用、外出交通費等費用（下稱雜項費用）。乙方於甲方之購買專案與範圍內，接受甲方之書面指示執行本專案，如甲方有超出本報價單及其附件所載專案以外之請求，雙方應另以書面協議費用後進行。\"\n      },\n      {\n        \"no\": 3,\n        \"text\": \"如有雜項費用產生，其金額實支實付，由乙方每月月結向甲方請款。\"\n      },\n      {\n        \"no\": 4,\n        \"text\": \"本合約專案如屬指令碼製作，而有外出拍攝或其他特殊企劃需求者，經甲乙雙方商議後，得視情況置換規格；本合約專案如以時間為計費單位之報價，將依實際拍攝內容之增減專案，由雙方以書面調整作為專案之實際費用，不以本報價單所載內容為限。\"\n      },\n      {\n        \"no\": 5,\n        \"text\": \"甲方不得指定乙方洽談特定之KOL並與其簽訂合作合約之條件。\"\n      },\n      {\n        \"no\": 6,\n        \"text\": \"甲方應提供相關編輯素材及所需資料（下簡稱素材）供乙方執行專案產出之編排，並就其提供之素材所含之智慧財產權授權乙方於本專案範圍及目的內使用。乙方不得意圖以自己或第三人利益而使用甲方提供之素材或有任何違反甲方授權範圍及目的之利用行為。乙方對於甲方提供之素材不侵害他人智慧財產權或其他權利，或不違反中華民國法令，不負保證之責。\"\n      },\n     {\n        \"no\": 7,\n        \"text\": \"乙方於合約期間內，工作成果應交由甲方對其內容進行審稿、提供編修意見並確認後始得發布。甲方於各項專案享有三次之提出修改權利，乙方應於甲方提出修改要求後，於雙方所訂期間內完成修改並再次提供甲方審稿。如甲方修改需求超過前述次數，由雙方另以書面協議額外之費用後始得執行；如協議不成或乙方認甲方之修改請求窒礙難行，乙方有權終止本合約，已支付費用不予退還。\"\n      },\n      {\n        \"no\": 8,\n        \"text\": \"甲方對於本專案工作成果之修改如有變更或經雙方評估後需重新拍攝而超過專案規格或內容時，乙方得依甲方需求提出報價，雙方應另以書面協議費用與完成工作之時間表。\"\n      },\n      {\n        \"no\": 9,\n        \"text\": \"乙方經甲方審查以書面確認後即送交執行程式，將不再接受甲方之修改請求。甲方如認有修改之必要，應由雙方另以書面協議費用，並由甲方支付費用後始得為之。\"\n      },\n      {\n        \"no\": 10,\n        \"text\": \"乙方完成本專案工作後，應以書面通知甲方結案；甲方如有留存短影音、原始圖文等工作成果之需求，應於收受通知日起十四個工作日之內請求乙方提供原始檔案並下載、備份完畢，如逾期乙方不負原始檔之提供、儲存義務。\"\n      },\n      {\n        \"no\": 11,\n        \"text\": \"當月文章如無故或因乙方疏失，經每月底盤點後發現文章被刪文，乙方有義務於次月或合約期間內免費補上文章，但若為乙方曾經制止之高風險文章，因甲方堅持上刊後導致被刪文，則不在乙方義務免費補文範疇。\"\n      },\n      {\n        \"no\": 12,\n        \"text\": \"規格已實際執行為主，乙方享有彈性調整之權利。對於整體議題發布，乙方可做適當之調整與變動；如遇網路或實體各委刊平臺特殊異常之情況，乙方得以新呈現方式之同等價格做版面更替。如甲方堅持上刊乙方認為不適合的文章、版位，導致文章上線後引來帳號折損或影響乙方其他品牌客戶，乙方有權向甲方索取賠償。\"\n      },\n      {\n        \"no\": 13,\n        \"text\": \"彈性迴文之使用為求時效與真實性，會依據文章討論狀況並經過雙方定調「操作方向」後，授權乙方直接進行操作，無須過稿。\"\n      },\n      {\n        \"no\": 14,\n        \"text\": \"針對論壇文章內容、版位，或文章涉及被質疑業配等負面風險，乙方有最終修改權以及最終裁決上刊與否權力。\"\n      },\n      {\n        \"no\": 15,\n        \"text\": \"若文章經刊登後引來大量負面聲量，為維護帳號與其他文章，乙方有權拒絕甲方要求置入品牌資訊。但乙方也需要將此篇數等比例補至其他操作中。\"\n      },\n      {\n        \"no\": 16,\n        \"text\": \"大型物件、貴重或易碎物品均由甲方直接寄送給乙方人選，若是需要回收，回收衍伸之相關費用由甲方承擔負責。\"\n      },\n      {\n        \"no\": 17,\n        \"text\": \"若服務專案為部落客、網紅藝人等KOL，甲方均不得於乙方提供名單後越過乙方與名單中的人選直接合作。如途中任意取消或發現甲方越過乙方則按委刊賠償總金額50%。\"\n      },\n      {\n        \"no\": 18,\n        \"text\": \"社群維運素材製作，動圖或插畫型等圖片要求，將依實際需求難易度另行報價。\"\n      },\n      {\n        \"no\": 19,\n        \"text\": \"甲方理解乙方基於Facebook / GoogleAds產品平臺正常執行、市場利益考量與經營需要，Facebook / GoogleAds會有定期或不定期對乙方產品平臺進行停機維護， 甚至對於網站服務內容、版面佈局、頁面設計等相關方面進行調整等此類情況，可能造成廣告帳號業務服務不能如期按委託內容執行，甲方承諾對此不追究乙方法律責任。\"\n      },\n      {\n        \"no\": 20,\n        \"text\": \"廣告主須自行監控連結的網站頁面，如因網站主機當機、網址失效、網頁名稱更動等因素造成之連結無效及非乙方操作失誤導致錯誤之原因， 廣告媒體商、確認鍵網路行銷有限公司皆不負損失賠償。\"\n      },\n      {\n        \"no\": 21,\n        \"text\": \"雙方簽署合約後，為達到甲乙雙方有效溝通、提高工作效率，乙方應依甲方指示指定聯絡人組建LINE工作群組負責與甲方接洽，並提供雲端作業Cue表、執行作業細節、工作天數等流程備忘。甲方如有會議需要，乙方亦應派人與會；乙方聯絡人如有調動，應經甲方書面同意後始可為之；如甲方認乙方聯絡人不符需求，乙方應依甲方指示積極配合調換。\"\n      }\n]\n  },\n  {\n \"title\": \"付款方式\",\n    \"items\": [\n      {\n        \"no\": 22,\n        \"text\": \"本專案與廣告投放相關費用皆需先全額付清才可執行，如其他產品專案已達專案結案時間尚未結案，乙方有權依照已執行規格先結算費用。若專案已執行50%以上，則甲方需支付50%專案費用，如結案超過一個月以上，甲方需同意乙方請款剩餘80%費用，如超過結案三個月，甲方需同意乙方剩餘請款100%費用，甲方需同意已方請款80%。如甲方以支付全額，則不在此限。\"\n      },\n      {\n        \"no\": 23,\n        \"text\": \"乙方應依前條開立發票，甲方於收到發票後於30天內以匯款方式支付款項至乙方指定帳號。\"\n      },\n      {\n        \"no\": 24,\n        \"text\": \"甲方至遲應於「廣告之目的」已達成時作為支付尾款期限，甲方不得以任何理由遲延、少付或拒付費用。如逾期支付本合約之任何費用，乙方有權依照逕向法院聲請支付命令、提起訴訟，甲方不得異議。\"\n      }\n]\n  },\n  {\n \"title\": \"智慧財產權\",\n    \"items\": [\n      {\n        \"no\": 25,\n        \"text\": \"甲方保證本專案之委託目的與工作內容及提供之素材不侵害他人之權利、智慧財產權及違反中華民國法令。如有第三人對乙方主張甲方之專案目的與工作內容侵害其智慧財產權或其他權利，或因甲方違背法令致乙方受政府機關裁罰，甲方除應自行負責處理爭議，並應賠償乙方所受之損害（包括但不限於所有訴訟、和解、律師費、罰鍰、罰金及其他相關衍生費用支出）。乙方並得於通知甲方後單方終止本合約，停止本專案之執行並，已收受之費用將不予退還。\"\n      },\n      {\n        \"no\": 26,\n        \"text\": \"乙方為甲方製作之專案，不得違反著作權法，如有違反著作權之爭議，甲方得拒絕驗收或支付費用至該爭議釐清止，且相關法律責任由乙方自行負責。乙方因甲方提供之素材而違反著作權法者，不在此限。\"\n      },\n      {\n        \"no\": 27,\n        \"text\": \"乙方依本專案製作之實拍、影音等相關產出，其智慧財產權約定於甲方付清本專案所有費用後歸屬於甲方。惟甲方同意乙方於商業推廣目的範圍內（如於乙方官網、社群媒體、客戶簡報中呈現過往合作客戶、成功案例等），得公開展示或重製甲方之智慧財產權。甲方得隨時請求乙方停止使用其智慧財產於商業推廣，乙方不得拒絕。\"\n      },\n      {\n        \"no\": 28,\n        \"text\": \"甲方專案期間內已公開上傳之檔案，不必於專案期滿後下架，但相關權利未經雙方延展、授權不得再度發表、重製、編輯、改作、散佈、公開播送、公開發表、公開展示、公開上映。\"\n      }\n]\n    },\n  {\n \"title\": \"違約及終止事由\",\n    \"items\": [\n      {\n        \"no\": 29,\n        \"text\": \"除乙方交付之檔案與執行表單間有缺件、明顯色調差異、正反面錯誤、缺少必須道具情形等可歸責於乙方事由發生外，如需重新執行案件製作，費用為報價金額之原價。\"\n      },\n      {\n        \"no\": 30,\n        \"text\": \"甲方遲延支付本專案費用者，每遲延一日以專案總價費用之 0.5% 加計懲罰性違約金，以專案總價之 100% 為違約金上限。\"\n      },\n      {\n        \"no\": 31,\n        \"text\": \"如因可歸責於甲方事由致本合約專案進度未能於報價單所載期間內完成，或未能達成雙方訂定之 KPI 者，乙方不負任何賠償責任，甲方亦不得以未完成工作或 KPI 未達標而遲延、少付或拒付費用；如專案自報價單所載期間末日起遲延逾一個月以上，乙方得逕行終止本合約，或甲方每月應支付乙方新台幣 6,000 元之專案管理費（不足一個月以一個月計）。\"\n      },\n      {\n        \"no\": 32,\n        \"text\": \"本合約生效後，非經雙方書面同意，不得任意終止或變更合約。如甲方提前終止合約，乙方將取消專案優惠價格以原價計算，甲方應補齊已執行費用與原價差額予乙方，甲方並應支付違約金新台幣5萬元。如專案工作涉及短影音拍攝，應另按已拍攝每支影片費用以原價之75%作為違約金；若短影音已剪輯，並應另按每支影片費用以原價之100%作為違約金，除違約金外已拍攝影片所產生之交通費、素材費、場租費等實支實付費用亦由甲方承擔。\"\n      }\n]\n    },\n  {\n \"title\": \"保密義務\",\n    \"items\": [\n      {\n        \"no\": 33,\n        \"text\": \"乙方同意因參與本專案而知悉或持有甲方之商業機密及其他機密資訊，負有保密義務，乙方不得以任何方法洩漏或公開予其他第三人，亦不得為自己或其他人之利益，使用該資訊。乙方違反本契約之約定者，甲方有權立即終止本契約，若甲方受有損害時，甲方並得向乙方請求損害賠償。乙方員工之違約行為，亦視為乙方之違約。\"\n      }\n]\n    },\n  {\n \"title\": \"準據法與管轄\",\n    \"items\": [\n      {\n        \"no\": 34,\n        \"text\": \"若因本合約未能履行或履行不力所生之爭議糾紛，雙方同意先本誠信原則磋商之。\"\n      },\n      {\n        \"no\": 35,\n        \"text\": \"本合約以中華民國法律為準據法。如因本合約涉訟，雙方同意以台灣臺北地方法院作為第一審管轄法院。\"\n      }\n]\n    },\n  {\n \"title\": \"其他事項\",\n    \"items\": [\n      {\n        \"no\": 36,\n        \"text\": \"本合約取代甲乙雙方先前之一切口頭、書面之要約、承諾、保證或合意。\"\n      },\n      {\n        \"no\": 37,\n        \"text\": \"本合約未約定事項，雙方得以書面方式另行約定，修正時亦同。\"\n      },\n      {\n        \"no\": 38,\n        \"text\": \"本合約之附件視為合約一部份，本合約未約定事項以附件為準；如附件與本合約牴觸者，優先適用本合約之約定。本合約計一式二份，由甲乙雙方各執乙份為憑。\"\n      },\n      {\n        \"no\": 39,\n        \"text\": \"本合約報價單開立日為____年___月___日，自該日起一個月內有效，逾期本合約、報價單及附件等一切書面對雙方不生拘束。\"\n      }\n]\n  }\n]', 0, '報價單預覽和PDF匯出使用，JSON格式：[{title,items:[{no,text}]}]');
INSERT INTO `base_sys_param` VALUES (7, '2026-05-14 16:41:34', '2026-06-02 15:20:45', NULL, 'crmMail', 'CRM郵件傳送配置', '{\"host\":\"smtp.163.com\",\"port\":465,\"secure\":true,\"user\":\"querenjian2026@163.com\",\"pass\":\"WZcAWsR343JJYjLT\",\"from\":\"querenjian2026@163.com\",\"senderName\":\"\"}', 0, 'CRM郵件傳送方配置；163信箱使用授權碼作為 pass');
INSERT INTO `base_sys_param` VALUES (8, '2026-05-16 10:39:29', '2026-05-16 10:39:29', NULL, 'quote_payment_condition', '報價單付款條件', '付款方式：專案金額(含營業稅)共計新台幣 {finalAmount} 元整，甲方於收到發票後，30 天內以匯款方式支付款項至乙方指定帳號，匯款後提供後五碼及匯款日期以便甲方核對。\n*本欄請注意：本單須雙方簽立完成後，送交乙方才會始得進行委刊作業。', 0, '報價單預覽和PDF匯出使用；支援佔位符 {finalAmount} 或 {amount}');
INSERT INTO `base_sys_param` VALUES (9, '2026-05-16 11:27:38', '2026-05-16 11:41:52', NULL, 'quote_party_b', '報價單乙方資料', '{\n  \"companyName\": \"確認鍵智創科技股份有限公司\",\n  \"address\": \"臺北市中正區福州街43巷11號\",\n  \"taxNumber\": \"83516691\",\n  \"contactName\": \"vicky\",\n  \"email\": \"vicky@enterimc.com\",\n  \"mobile\": \"123456789\",\n  \"bankAccountName\": \"確認鍵智創科技股份有限公司\",\n  \"bankCode\": \"012\",\n  \"bankName\": \"臺北富邦銀行\",\n  \"bankAccountNo\": \"82110000259100\"\n}', 0, '報價單預覽和PDF匯出使用，JSON格式；bankCoverUrl 為乙方存摺封面圖片地址');
INSERT INTO `base_sys_param` VALUES (10, '2026-05-16 11:32:17', '2026-06-05 11:59:06', NULL, 'quote_bank_cover', '報價單乙方存摺封面', 'https://crm-bucket-66.s3.ap-east-1.amazonaws.com/app%2Fbase%2Fpgfm_026f2491740943ea9e3fcd1b0398f912.jpg', 2, '報價單預覽使用；參數型別選擇檔案，可上傳一張封面圖片');
INSERT INTO `base_sys_param` VALUES (11, '2026-05-16 11:53:42', '2026-06-05 11:53:50', NULL, 'quote_company_seal', '報價單乙方公章', 'https://crm-bucket-66.s3.ap-east-1.amazonaws.com/app%2Fbase%2F%E8%92%99%E7%89%88%E7%BB%84%202342%404x_14258b45ea3d40f49a42d30b4e0e00eb.png', 2, '報價單公章預覽使用；參數型別選擇檔案，可上傳一張圖片，必選使用透明背景公章圖片');
INSERT INTO `base_sys_param` VALUES (12, '2026-05-19 14:50:21', '2026-06-05 16:42:43', NULL, 'crmInvoiceMailTemplate', 'CRM發票郵件模板', '{\"subject\":\"確認鍵發票_{{quoteName}}{{invoicePeriodText}}\",\"html\":\"<div style=\\\"font-family: Arial, \'Microsoft JhengHei\', sans-serif; line-height: 1.8; color: #333;\\\"><p>您好，</p><p>附件為「{{quoteName}}{{invoicePeriodText}}」發票，敬請查收。</p><p>若有任何問題，再請不吝告知，謝謝。</p><p>祝 順心</p><p>確認鍵智創科技股份有限公司</p></div>\",\"text\":\"您好，\\n附件為「{{quoteName}}{{invoicePeriodText}}」發票，敬請查收。\\n若有任何問題，再請不吝告知，謝謝。\\n祝 順心\\n確認鍵智創科技股份有限公司\",\"attachments\":[]}', 0, '發票郵件內容模板；固定 keyName；支援 attachments 陣列，例如 [{\"filename\":\"附件.pdf\",\"path\":\"D:/file/附件.pdf\"}]');
INSERT INTO `base_sys_param` VALUES (13, '2026-05-19 14:50:21', '2026-06-06 13:37:33', NULL, 'crmCustomerMailTemplate', 'CRM客戶公池郵件模板', '<p>主題：如何讓品牌的行銷內容製作成本降 50% ，並創造10倍流量？</p><p style=\"text-align: start;\"><span style=\"background-color: transparent;\">您好：</span></p><p style=\"text-align: start;\"><span style=\"background-color: transparent;\">在 AI 世代，您的行銷策略跟上了嗎？</span></p><p style=\"text-align: start;\"><span style=\"background-color: transparent;\">當所有人都能快速產製內容，品牌要如何用更少的預算，創造更高的聲量與轉換？</span></p><p style=\"text-align: start;\"><br></p><p style=\"text-align: start;\">我們是 <strong>確認鍵智創科技（Enter.AI ）</strong>，</p><p style=\"text-align: start;\">一間專注於 <strong>AI 驅動整合行銷</strong> 的團隊。</p><p style=\"text-align: start;\">我們的使命是成為您<strong>「最高CP值的品牌行銷夥伴</strong>」，</p><p style=\"text-align: start;\">以 <strong>資料驅動 × 彈性預算 × 火速破圈</strong> 的策略，</p><p style=\"text-align: start;\">讓您的品牌 <span style=\"color: rgb(66, 144, 247);\">Everywhere 被看見、被分享、被討論。</span></p><p style=\"text-align: start;\"><img src=\"https://crm-bucket-66.s3.ap-east-1.amazonaws.com/app%2Fbase%2Fimage_8c8b33cd64cf46e896549682f924c018.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"></p><h3><span style=\"font-size: 24px;\"><strong>我們服務過的品牌</strong></span></h3><p>您一定看過我們的內容。<br>我們服務過眾多知名品牌——從 <strong>臺塑生醫、肯德基、PChome、LG、YAMAHA、Kanebo、Yahoo!</strong> 到 <strong>新光三越、FamilyMart</strong> 等各領域客戶。</p><p><img src=\"https://crm-bucket-66.s3.ap-east-1.amazonaws.com/app%2Fbase%2Fimage_f4794ac4c0c7478f84f32ba7ae479a27.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"/></p><h3 style=\"text-align: start;\"><span style=\"background-color: transparent; font-size: 19px;\"><strong>一站式全域整合行銷服務</strong></span></h3><p style=\"text-align: start;\"><span style=\"background-color: transparent;\"><strong>只有想不到沒有做不到，有想法就能實現。</strong></span></p><p style=\"text-align: start;\"><span style=\"background-color: transparent;\">我們提供從策略到執行的全行銷整合，</span></p><p style=\"text-align: start;\"><span style=\"background-color: transparent;\">以 AI 為驅動引擎，融合創意策略、演算法運算與系統資料分析，打造具擴散力與轉換力的全域行銷佈局。</span></p><p style=\"text-align: start;\"><span style=\"background-color: transparent;\"><strong>服務範圍包括：</strong></span></p><ul><li style=\"text-align: start;\">Threads 口碑行銷</li><li style=\"text-align: start;\">KOL／KOC 行銷</li><li style=\"text-align: start;\">社群經營與內容操作（含 Threads、短影音）</li><li style=\"text-align: start;\">AIGC 視覺設計與內容生成</li><li style=\"text-align: start;\">全渠道廣告投放（Meta、Google、Tiktok、小紅書）</li><li style=\"text-align: start;\">媒體公關與 SEO／GEO 搜尋佈局</li></ul><p><img src=\"https://crm-bucket-66.s3.ap-east-1.amazonaws.com/app%2Fbase%2Fimage_b4946750aa704867886e8085d3c2763e.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"/></p><h3 style=\"text-align: start;\"><span style=\"background-color: transparent; font-size: 22px;\"><strong>實際成功案例：臺塑生醫健康悠活館</strong></span></h3><p style=\"text-align: start;\"><span style=\"background-color: transparent; font-size: 14px;\"><strong>挑戰：</strong></span><span style=\"background-color: transparent;\">傳統媒體投放成效有限、觸及流量難以突破。</span></p><p style=\"text-align: start;\"><span style=\"background-color: transparent; font-size: 14px;\"><strong>策略：</strong></span><span style=\"background-color: transparent;\">透過 KOC/KOL 曝光、Threads 話題操作、社群經營與媒體報導同步發酵。</span></p><p style=\"text-align: start;\"><span style=\"background-color: transparent;\">成果：</span></p><ul><li style=\"text-align: start;\"><span style=\"background-color: transparent;\"><strong>創造</strong></span><span style=\"color: rgb(89, 191, 192); background-color: transparent;\"><strong> 210萬 TikTok</strong></span><span style=\"background-color: transparent;\"><strong> 觀看數</strong></span></li><li style=\"text-align: start;\"><span style=\"background-color: transparent;\">超過 500 則 IG 打卡與新聞媒體自主報導</span></li><li style=\"text-align: start;\"><span style=\"background-color: transparent;\"><strong>現場人流 </strong></span><span style=\"color: rgb(89, 191, 192); background-color: transparent;\"><strong>成長 10 倍以上</strong></span><span style=\"background-color: transparent;\"><strong>，商品全面熱銷缺貨</strong></span></li><li style=\"text-align: start;\"><span style=\"background-color: transparent;\">品牌榮獲「最佳網路行銷獎」殊榮</span></li></ul><p style=\"text-align: start;\"><img src=\"https://crm-bucket-66.s3.ap-east-1.amazonaws.com/app%2Fbase%2Fimage_350a659dc6a140f0a5d8ebf0cbb1cd6f.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"></p><p style=\"text-align: start;\"><img src=\"https://crm-bucket-66.s3.ap-east-1.amazonaws.com/app%2Fbase%2Fimage_6279308d7e524693ae8f28e093930b09.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"></p><p style=\"text-align: start;\"><img src=\"https://crm-bucket-66.s3.ap-east-1.amazonaws.com/app%2Fbase%2Fimage_d62b3f6739f342ae8c3811fe8ee0f7e8.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"></p><h3 style=\"text-align: start;\"><span style=\"background-color: transparent; font-size: 19px;\"><strong>AIGC 設計 × 內容製作成本減少50%</strong></span></h3><p style=\"text-align: start;\"><span style=\"background-color: transparent;\">在生成式 AI 崛起的時代，我們幫助品牌以更聰明的方式創造內容。</span></p><p style=\"text-align: start;\"><span style=\"color: rgb(89, 191, 192); background-color: transparent;\">確認鍵不是賣 AI 工具，而是「會用 AI 的設計團隊」。</span></p><ul><li style=\"text-align: start;\"><span style=\"background-color: transparent;\">廣告素材、電商設計圖、商攝情境照，一站式生成</span></li><li style=\"text-align: start;\"><span style=\"background-color: transparent;\"><strong>品質一致、</strong></span><span style=\"color: rgb(89, 126, 247); background-color: transparent;\"><strong>成本減少50%</strong></span></li><li style=\"text-align: start;\"><span style=\"background-color: transparent;\">快速製作多版本素材，提高 ROI 與投放靈活度</span></li></ul><p style=\"text-align: start;\"><br></p><p style=\"text-align: start;\"><span style=\"background-color: transparent;\"><strong>我們的 AIGC 服務包含：</strong></span></p><ul><li style=\"text-align: start;\"><span style=\"background-color: transparent;\">AI 視覺生成 × 品牌風格整合</span></li><li style=\"text-align: start;\"><span style=\"background-color: transparent;\">廣告素材快速產出</span></li><li style=\"text-align: start;\"><span style=\"background-color: transparent;\">商用級社群與電商設計圖</span></li><li style=\"text-align: start;\"><span style=\"background-color: transparent;\">內容授權全包，降低人力負擔</span></li></ul><p><img src=\"https://crm-bucket-66.s3.ap-east-1.amazonaws.com/app%2Fbase%2Fimage_faf02ff3f71b491380a1f5cb1bccc96d.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"/><br></p><p><img src=\"https://crm-bucket-66.s3.ap-east-1.amazonaws.com/app%2Fbase%2Fimage_a4950b0bfa3c4b6286658840e1caa1cb.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"/><br></p><p><img src=\"https://crm-bucket-66.s3.ap-east-1.amazonaws.com/app%2Fbase%2Fimage_68f9e56fc08a4ac8955a587932dd26be.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"/></p><h3><span style=\"background-color: transparent; font-size: 16px;\"><strong>KOC＋口碑行銷：品牌說不如客人說</strong></span></h3><p><span style=\"color: rgb(89, 191, 192); background-color: transparent;\">品牌能見度 ≠ 品牌好感度。</span></p><p><span style=\"background-color: transparent;\">我們擁有遍佈全臺的百萬級素人與網紅資源庫，</span></p><p><span style=\"background-color: transparent;\">擅長讓「討論」變成「行銷力」，以最自然的話題打進消費者社群圈。</span></p><ul><li><span style=\"background-color: transparent;\">資料篩選目標受眾與論壇族群</span></li><li><span style=\"background-color: transparent;\">創造UGC內容、觸發自主分享</span></li><li><span style=\"background-color: transparent;\">媒體跟進報導、形成話題漩渦</span></li></ul><p>這正是確認鍵的口碑行銷策略核心：<span style=\"color: rgb(54, 207, 201);\">眾口成金，話題造勢。</span></p><p><img src=\"https://crm-bucket-66.s3.ap-east-1.amazonaws.com/app%2Fbase%2Fimage_7e772d31eb7a49868e19577b8223fd50.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"/></p><p><img src=\"https://crm-bucket-66.s3.ap-east-1.amazonaws.com/app%2Fbase%2Fimage_745af419b2294b3b81b1d5711c1b6b64.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"/><br><img src=\"https://crm-bucket-66.s3.ap-east-1.amazonaws.com/app%2Fbase%2Fimage_31c7b11b1d6148b79423c871ba8eb4af.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"/></p><h3 style=\"text-align: start;\"><span style=\"background-color: transparent; font-size: 16px;\"><strong>GEO：AI世代的SEO革命</strong></span></h3><p style=\"text-align: start;\"><span style=\"background-color: transparent;\">傳統 SEO 已經不足以應付生成式 AI 的時代。確認鍵推出「GEO（Generative Engine Optimization）」，讓您的品牌內容出現在 ChatGPT、Gemini</span>、<span style=\"background-color: transparent;\">Perplexity 等 AI 搜尋結果中。</span><span style=\"color: rgb(0, 0, 0); background-color: transparent; font-size: 16px;\"><strong>結合內容工程 × 關鍵字佈局 × AI資料餵養提升品牌在 AI 回覆中的曝光機率</strong></span></p><p style=\"text-align: start;\"><span style=\"color: rgb(0, 0, 0); background-color: transparent; font-size: 16px;\"><strong>打造能被 AI「主動提及」的數位資產，讓AI自然推薦你</strong></span><strong>。</strong></p><p><img src=\"https://crm-bucket-66.s3.ap-east-1.amazonaws.com/app%2Fbase%2Fimage_237174aa499c46b08ef68161189ff3b2.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"/></p><p><img src=\"https://crm-bucket-66.s3.ap-east-1.amazonaws.com/app%2Fbase%2Fimage_e056e5daae4849a6a455d71a358de580.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"/></p><h3 style=\"text-align: start;\"><span style=\"background-color: transparent; font-size: 24px;\"><strong>為何選擇確認鍵？</strong></span></h3><ul><li style=\"text-align: start;\"><span style=\"background-color: transparent;\">一站式全域整合行銷</span></li><li style=\"text-align: start;\"><span style=\"background-color: transparent;\">AI 驅動的策略與設計團隊</span></li><li style=\"text-align: start;\"><span style=\"background-color: transparent;\">實績證明，品牌成長可被量化</span></li><li style=\"text-align: start;\"><span style=\"background-color: transparent;\">亞州市場佈局，國際視野操作</span></li></ul><p style=\"text-align: start;\"><br></p><p style=\"text-align: start;\"><span style=\"color: rgb(11, 83, 148);\"><strong>ENTER TO MAKE YOU EVERYWHERE.</strong></span></p><p style=\"text-align: start;\"><span style=\"color: rgb(11, 83, 148);\"><strong>我們讓品牌以最高效率，出現在消費者看見的每一個地方</strong></span><span style=\"background-color: transparent;\"><strong>。</strong></span></p><p><img src=\"https://crm-bucket-66.s3.ap-east-1.amazonaws.com/app%2Fbase%2Fimage_d72ae9bdabf64c73bff835608b86098d.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"/></p><p><span style=\"color: rgb(0, 0, 0); background-color: transparent;\">在這個內容快速迭代的時代，</span></p><p><span style=\"color: rgb(0, 0, 0); background-color: transparent;\">確認鍵不只是行銷公司，更是您品牌的 AI 成長引擎。</span></p><p><span style=\"color: rgb(0, 0, 0); background-color: transparent;\">讓我們用資料、創意與科技，</span></p><p><span style=\"color: rgb(0, 0, 0); background-color: transparent;\">一起讓您的品牌 —— Everywhere.</span></p><p><br></p><h3><span style=\"background-color: rgb(11, 83, 148);\">免費 30 分鐘行銷健檢</span></h3><p><span style=\"background-color: transparent;\">我們誠摯邀請您預約一次</span><span style=\"background-color: transparent;\"><strong>免費的「AI 行銷健檢會議」</strong></span><span style=\"background-color: transparent;\">，</span></p><p><span style=\"background-color: transparent;\">由顧問團隊為您的品牌客製化診斷策略，</span></p><p><span style=\"background-color: transparent;\">共同找出「降低成本 ×快速擴散 ×驅動轉換」的最佳方案。</span></p><p><span style=\"background-color: transparent;\">聯絡我們</span></p><p><span style=\"background-color: transparent;\">Line：@898fkbxz</span></p><p><span style=\"background-color: transparent;\">網站：</span><a href=\"https://reurl.cc/1K3rk9\" target=\"_blank\"><span style=\"background-color: transparent;\">https://enterimc.com/</span></a></p><p><br>--</p><p><img src=\"https://ci3.googleusercontent.com/mail-sig/AIorK4ylsWPdmpopNXc0H0XWSCEPNtKZ8XGXsY0OIEbEqCG933hL1S8HAmo26Sg8XpWapVXTP_BPYFgsaGIy\" alt=\"\" data-href=\"\" style=\"width: 95px;height: auto;\"/><br></p><p><span style=\"color: rgb(118, 113, 113);\"><em>確認鍵智創科技股份有限公司</em></span></p><p><span style=\"color: rgb(118, 113, 113);\"><em>242新北市新莊區新北大道三段220號5F</em></span><em>統編：83516691</em></p><p><em>公司電話：02-8521-2774</em></p>', 1, '客戶公池郵件富文本內容模板');
INSERT INTO `base_sys_param` VALUES (19, '2026-06-03 10:20:59', '2026-06-06 11:47:10', NULL, 'crmEcpayInvoice', 'CRM綠界發票開票配置', '{\"enabled\":true,\n\"env\":\"stage\",\n\"merchantId\":\"2000132\",\n\"hashKey\":\"ejCk326UnaZWKisg\",\n\"hashIv\":\"q9jcZX8Ib9LM8wYk\",\n\"taxType\":\"1\",\n\"invType\":\"07\",\n\"itemWord\":\"項\",\n\"timeout\":15000,\n\"mode\":\"b2b\",\n\"endpoint\":\"https://einvoice-stage.ecpay.com.tw/B2BInvoice/Issue\",\n\"invalidEndpoint\":\"https://einvoice-stage.ecpay.com.tw/B2BInvoice/Invalid\"}', 0, '綠界 B2B 電子發票 Issue 配置；測試與正式環境皆使用 B2BInvoice endpoint');
INSERT INTO `base_sys_param` VALUES (20, '2026-06-05 11:51:58', '2026-06-05 11:52:54', NULL, 'invoice_company_seal', 'CRM發票公章', 'https://crm-bucket-66.s3.ap-east-1.amazonaws.com/app%2Fbase%2Ffpz_06c4d70203a3487a8c8f37ed881a2fc0.jpg', 2, '發票審核與發票相關檔案使用；參數型別選擇檔案，請上傳發票公章圖片');
INSERT INTO `base_sys_param` VALUES (21, '2026-06-11 17:36:28', '2026-06-11 17:36:28', NULL, 'quote_discount_rate', '報價單優惠比例閾值', '10', 0, '新增報價單時預設帶入優惠折扣，請填 0-100 的百分比數字，例如 15 表示 15%');
INSERT INTO `base_sys_param` VALUES (22, '2026-06-11 17:37:34', '2026-06-11 17:37:34', NULL, 'employee_withholding_rate', '員工扣繳比例', '5', 0, '員工獎金核算扣繳比例，請填 0-100 的百分比數字，例如 5 表示 5%');

-- ----------------------------
-- Table structure for base_sys_role
-- ----------------------------
DROP TABLE IF EXISTS `base_sys_role`;
CREATE TABLE `base_sys_role`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `createTime` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '建立時間',
  `updateTime` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '更新時間',
  `tenantId` int NULL DEFAULT NULL COMMENT '租戶ID',
  `userId` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '使用者ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '名稱',
  `label` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '角色標籤',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '備註',
  `relevance` tinyint NOT NULL DEFAULT 0 COMMENT '資料權限是否關聯上下級',
  `menuIdList` json NOT NULL COMMENT '選單權限',
  `departmentIdList` json NOT NULL COMMENT '部門權限',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `IDX_469d49a5998170e9550cf113da`(`name` ASC) USING BTREE,
  UNIQUE INDEX `IDX_f3f24fbbccf00192b076e549a7`(`label` ASC) USING BTREE,
  INDEX `IDX_6f01184441dec49207b41bfd92`(`createTime` ASC) USING BTREE,
  INDEX `IDX_d64ca209f3fc52128d9b20e97b`(`updateTime` ASC) USING BTREE,
  INDEX `IDX_953dc26a4e8bd5d9c989295796`(`tenantId` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of base_sys_role
-- ----------------------------
