-- ----------------------------
-- Table structure for base_sys_user
-- ----------------------------
DROP TABLE IF EXISTS `base_sys_user`;
CREATE TABLE `base_sys_user`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `createTime` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '建立時間',
  `updateTime` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '更新時間',
  `tenantId` int NULL DEFAULT NULL COMMENT '租戶ID',
  `departmentId` int NULL DEFAULT NULL COMMENT '部門ID',
  `userId` int NULL DEFAULT NULL COMMENT '建立者ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '姓名',
  `englishName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '英文名稱',
  `username` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '使用者名稱',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '密碼',
  `passwordV` int NOT NULL DEFAULT 1 COMMENT '密碼版本, 作用是改完密碼，讓原來的token失效',
  `nickName` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '暱稱',
  `headImg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '頭像',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '手機',
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '信箱',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '備註',
  `status` int NOT NULL DEFAULT 1 COMMENT '狀態 0-停用 1-啟用',
  `socketId` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'socketId',
  `salary` decimal(10, 2) NULL DEFAULT NULL COMMENT '工資',
  `level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '級別',
  `withholdingSalary` decimal(10, 2) NULL DEFAULT NULL COMMENT '扣繳工資',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `IDX_469ad55973f5b98930f6ad627b`(`username` ASC) USING BTREE,
  INDEX `IDX_ca8611d15a63d52aa4e292e46a`(`createTime` ASC) USING BTREE,
  INDEX `IDX_a0f2f19cee18445998ece93ddd`(`updateTime` ASC) USING BTREE,
  INDEX `IDX_94cb6e88070603ac6729d514fd`(`tenantId` ASC) USING BTREE,
  INDEX `IDX_0cf944da378d70a94f5fefd803`(`departmentId` ASC) USING BTREE,
  INDEX `IDX_40541b0502eb2422c73ae2aad1`(`userId` ASC) USING BTREE,
  INDEX `IDX_9ec6d7ac6337eafb070e4881a8`(`phone` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 38 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

