-- ----------------------------
-- Table structure for crm_bonus_config
-- ----------------------------
DROP TABLE IF EXISTS `crm_bonus_config`;
CREATE TABLE `crm_bonus_config`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `createTime` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '建立時間',
  `updateTime` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '更新時間',
  `tenantId` int NULL DEFAULT NULL COMMENT '租戶ID',
  `roleType` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '適用角色 sales-業務 internal-內勤',
  `groupCode` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '分組編碼',
  `groupName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '分組名稱',
  `configCode` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '配置編碼',
  `configName` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '配置名稱',
  `configType` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '配置型別 rate-比例 amount-金額 threshold-門檻 text-文本',
  `conditionText` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '條件說明',
  `calcBase` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '計算基數',
  `configValue` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '配置值',
  `unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '單位',
  `sortNum` int NOT NULL DEFAULT 0 COMMENT '排序',
  `isEnabled` tinyint NOT NULL DEFAULT 1 COMMENT '啟用狀態 0-停用 1-啟用',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '備註',
  `isDeleted` tinyint NOT NULL DEFAULT 0 COMMENT '邏輯刪除 0-否 1-是',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `IDX_2507e01b7f7194d783c69a9826`(`configCode` ASC) USING BTREE,
  INDEX `IDX_f1ea6f91ffc32f32f6e88e3002`(`createTime` ASC) USING BTREE,
  INDEX `IDX_b4927ec12774cc4fbb91e653a3`(`updateTime` ASC) USING BTREE,
  INDEX `IDX_e712cfb7189494c45ee00ab0b5`(`tenantId` ASC) USING BTREE,
  INDEX `IDX_556d14637c8a46e50e8d8f8946`(`roleType` ASC) USING BTREE,
  INDEX `IDX_8b05506946e40eb86c66e18ba0`(`groupCode` ASC) USING BTREE,
  INDEX `IDX_3bcb80275c47e0da5cbd150d5f`(`isEnabled` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 41 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

