  `isDeleted` tinyint NOT NULL DEFAULT 0 COMMENT '邏輯刪除 0-否 1-是',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `UK_crm_contract_reminder_user_date_deleted`(`userId` ASC, `notifyDate` ASC, `isDeleted` ASC) USING BTREE,
