-- ----------------------------
-- Table structure for crm_customer_info
-- ----------------------------
DROP TABLE IF EXISTS `crm_customer_info`;
CREATE TABLE `crm_customer_info`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `createTime` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '建立時間',
  `updateTime` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '更新時間',
  `tenantId` int NULL DEFAULT NULL COMMENT '租戶ID',
  `companyName` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '公司名稱',
  `address` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '地址',
  `taxNumber` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '統一編號',
  `remittanceLast5` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '匯款末五碼',
  `contactName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '客戶名稱/聯絡人',
  `mobile` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '手機號碼',
  `email` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '信箱',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '備註',
  `isVip` tinyint NOT NULL DEFAULT 0 COMMENT '是否VIP 0-否 1-是',
  `salesmanId` int NULL DEFAULT NULL COMMENT '業務員ID，空表示在公池',
  `isDeleted` int NOT NULL DEFAULT 0 COMMENT '邏輯刪除 0-否 1-是',
  `industry` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '行業(字典crmIndustry)',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '客戶狀態 1-跟進中 2-已失效 3-報價中 4-已發報價單 5-報價審核中 6-已完成',
  `dealCount` int NOT NULL DEFAULT 0 COMMENT '累計成交次數',
  `dealAmount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '累計成交金額',
  `isAdCustomer` tinyint NOT NULL DEFAULT 0 COMMENT '是否廣告投放客戶 0-否 1-是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_070b0f73471d94647f49eab567`(`createTime` ASC) USING BTREE,
  INDEX `IDX_d0254674afad11ebf5b1b12761`(`updateTime` ASC) USING BTREE,
