  INDEX `IDX_b2836de349a516427f2ce96bc5`(`mobile` ASC) USING BTREE,
  INDEX `IDX_bcf296ebc91a7b224acdddf575`(`salesmanId` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1024 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

