-- ----------------------------
-- Table structure for crm_performance
-- ----------------------------
DROP TABLE IF EXISTS `crm_performance`;
CREATE TABLE `crm_performance`  (
  `createTime` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '建立時間',
  `updateTime` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新時間',
  `tenantId` int NULL DEFAULT NULL COMMENT '租戶ID',
  `performanceMonth` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '考核月份 YYYY-MM',
  `performanceName` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '獎金名稱',
  `userId` int NOT NULL COMMENT '考核使用者ID',
  `userName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考核使用者名稱稱',
  `roleType` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '考核角色 sales-業務 internal-內勤',
  `periodStart` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '考核開始時間',
  `periodEnd` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '考核結束時間',
  `invoiceAmount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '本月開票金額',
  `expectedBonus` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '預計獎金',
  `receiptAmount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '本月回款金額',
  `actualBonus` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '實際獎金',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '狀態 1-未申請 2-已申請 3-已完成',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '備註',
  `isDeleted` tinyint NOT NULL DEFAULT 0 COMMENT '邏輯刪除 0-否 1-是',
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `UK_crm_performance_month_user_role_deleted`(`performanceMonth` ASC, `userId` ASC, `roleType` ASC, `isDeleted` ASC) USING BTREE,
  INDEX `IDX_6ecf21fd0fc9db1cf61355ec55`(`createTime` ASC) USING BTREE,
  INDEX `IDX_4d7c589e4ec882ce252030c1ae`(`updateTime` ASC) USING BTREE,
  INDEX `IDX_f43c7908e415646528c55feadd`(`tenantId` ASC) USING BTREE,
  INDEX `IDX_52753be56f5298e82e3f2a2ae6`(`performanceMonth` ASC) USING BTREE,
  INDEX `IDX_98d506fda6569b7361f98753ab`(`userId` ASC) USING BTREE,
  INDEX `IDX_69baad67f1bd94fa95cd0e3c16`(`roleType` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for crm_quote_invoice
-- ----------------------------
DROP TABLE IF EXISTS `crm_quote_invoice`;
CREATE TABLE `crm_quote_invoice`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `createTime` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '建立時間',
  `updateTime` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '更新時間',
  `tenantId` int NULL DEFAULT NULL COMMENT '租戶ID',
  `invoiceNo` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '發票ID',
  `quoteOrderId` int NOT NULL COMMENT '報價單ID',
  `quoteStageId` int NOT NULL COMMENT '付款階段ID',
  `quoteNo` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '報價單編號',
  `quoteName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '專案名稱',
  `stageNo` int NOT NULL DEFAULT 1 COMMENT '付款階段',
  `stageName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '階段名稱',
  `ratio` decimal(8, 4) NOT NULL DEFAULT 0.0000 COMMENT '付款比例',
  `amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '發票金額',
  `invoiceProductName` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '開票產品',
