  `endDate` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '專案結束日期',
  `finalAmount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '報價總金額',
  `costAmount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '總成本',
  `grossProfitAmount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '毛利金額',
  `grossProfitRate` decimal(8, 4) NOT NULL DEFAULT 0.0000 COMMENT '毛利率',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '備註',
  `isDeleted` tinyint NOT NULL DEFAULT 0 COMMENT '邏輯刪除 0-否 1-是',
  `auditUserId` int NULL DEFAULT NULL COMMENT '審核人ID',
  `auditTime` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '審核時間',
  `auditRemark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '審核備註',
  `assignUserId` int NULL DEFAULT NULL COMMENT '分配人ID',
  `assignTime` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分配時間',
  `assignRemark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '分配備註',
  `sendType` tinyint NOT NULL DEFAULT 0 COMMENT '傳送方式 0-未傳送 1-郵件傳送 2-手工標記',
  `sendEmail` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '傳送信箱',
  `sendUserId` int NULL DEFAULT NULL COMMENT '傳送人ID',
  `sendTime` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '傳送時間',
  `sendRemark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '傳送備註',
  `contractFile` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '合約檔案地址',
  `contractFileName` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '合約檔名',
  `contractUploadUserId` int NULL DEFAULT NULL COMMENT '合約上傳人ID',
