  `contractRemark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '合約備註',
  `discountDeductionAmount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '優惠超出15%扣除獎金金額',
  `discountRate` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '優惠比例',
  `commission` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '佣金',
