  `projectStatus` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '項目狀況',
  `projectStatusImages` json NULL COMMENT '項目狀況圖片',
  `projectCueSheet` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '項目雲端Cue表',
  `priceRemark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '價格備註',
  `allowanceApplyStatus` tinyint NOT NULL DEFAULT 0 COMMENT '折讓申請狀態 0-未申請 1-已確認',
  `allowanceApplyUserId` int NULL DEFAULT NULL COMMENT '折讓申請人ID',
  `allowanceApplyTime` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '折讓申請時間',
  `quoteTerms` json NULL COMMENT '報價單條款',
  `caseMeetingFlag` tinyint NOT NULL DEFAULT 1 COMMENT '是否召開案情會議 0-否 1-是',
  `caseMeetingUpdateUserId` int NULL DEFAULT NULL COMMENT '案情會議更新人ID',
  `caseMeetingUpdateTime` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '案情會議更新時間',
  `discountAuditStatus` tinyint NOT NULL DEFAULT 0 COMMENT '優惠審批狀態 0-無需審批 1-待老闆審批 2-直接同意 3-同意扣除超出獎金 4-不同意',
  `discountAuditReason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '優惠審批原因',
  `discountAuditUserId` int NULL DEFAULT NULL COMMENT '優惠審批人ID',
  `discountAuditTime` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '優惠審批時間',
  `discountAuditRemark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '優惠審批備註',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_1e0434488c0fdcbb447543052d`(`createTime` ASC) USING BTREE,
  INDEX `IDX_f752b65f83e058c20654d7139c`(`updateTime` ASC) USING BTREE,
