  INDEX `IDX_8d087101d4e0f216a10a3cdefc`(`customerId` ASC) USING BTREE,
  INDEX `IDX_19d39712d112899ab75092958b`(`salesmanId` ASC) USING BTREE,
  INDEX `IDX_2b15af0661182608f205991771`(`currentAssigneeId` ASC) USING BTREE,
  INDEX `idx_quote_order_accompany_salesman_id`(`accompanySalesmanId` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

