  `remittanceName` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '匯款專案名稱',
  `quoteOrderId` int NULL DEFAULT NULL COMMENT '關聯報價單ID',
  `remittanceType` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '匯款型別',
  `supplierId` int NULL DEFAULT NULL COMMENT '供應商ID',
  `supplierCompanyName` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '供應商公司名稱',
  `supplierAddress` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '供應商地址',
  `supplierUnifiedNo` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '供應商統一編號',
  `supplierEmail` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '供應商信箱',
  `totalAmount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '匯款總價',
  `paidAmount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '已匯款金額',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '狀態 1-匯款中 2-已完成',
  `salesmanId` int NULL DEFAULT NULL COMMENT '業務員ID',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '備註',
  `isDeleted` tinyint NOT NULL DEFAULT 0 COMMENT '邏輯刪除 0-否 1-是',
  `uploadFiles` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '上傳檔案',
  `invoiceFiles` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '上傳發票',
  `accountInfo` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '賬戶資訊',
  `receivedLaborInsurance` tinyint NOT NULL DEFAULT 0 COMMENT '是否收到勞保單 0-否 1-是',
  `receivedInvoice` tinyint NOT NULL DEFAULT 0 COMMENT '是否收到發票 0-否 1-是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_b4a2df1b7d9ed1cd420ee71955`(`createTime` ASC) USING BTREE,
  INDEX `IDX_6ec8aa7d3624ae9c6731ec1dd1`(`updateTime` ASC) USING BTREE,
