-- ----------------------------
-- Table structure for task_info
-- ----------------------------
DROP TABLE IF EXISTS `task_info`;
CREATE TABLE `task_info`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `createTime` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '建立時間',
  `updateTime` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '更新時間',
  `tenantId` int NULL DEFAULT NULL COMMENT '租戶ID',
  `jobId` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '任務ID',
  `repeatConf` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '任務配置',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '名稱',
  `cron` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'cron',
  `limit` int NULL DEFAULT NULL COMMENT '最大執行次數 不傳為無限次',
  `every` int NULL DEFAULT NULL COMMENT '每間隔多少毫秒執行一次 如果cron設定了 這項設定就無效',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '備註',
  `status` int NOT NULL DEFAULT 1 COMMENT '狀態 0-停止 1-執行',
  `startDate` datetime NULL DEFAULT NULL COMMENT '開始時間',
  `endDate` datetime NULL DEFAULT NULL COMMENT '結束時間',
  `data` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '資料',
  `service` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '執行的service例項ID',
  `type` int NOT NULL DEFAULT 0 COMMENT '狀態 0-系統 1-使用者',
  `nextRunTime` datetime NULL DEFAULT NULL COMMENT '下一次執行時間',
  `taskType` int NOT NULL DEFAULT 0 COMMENT '狀態 0-cron 1-時間間隔',
  `lastExecuteTime` datetime NULL DEFAULT NULL,
  `lockExpireTime` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_6ced02f467e59bd6306b549bb0`(`createTime` ASC) USING BTREE,
  INDEX `IDX_2adc6f9c241391126f27dac145`(`updateTime` ASC) USING BTREE,
  INDEX `IDX_11b991dc4a7a5585c636008d3a`(`tenantId` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

